public int connectingRopesMinimumCost(int[] A) {
    PriorityQueue<Integer> minHeap = new PriorityQueue<>();
    for (int len : A) {
        minHeap.add(len);
    }
    long totalCost = 0;
    while (minHeap.size() > 1) {
        int x = minHeap.poll();
        int y = minHeap.poll();
        int cost = x + y;
        totalCost = totalCost + cost;
        minHeap.add(cost); // the merged rope competes for the next merge
    }
    return (int) totalCost;
}

public int[] buildMinHeapFromArray(int[] A) {
    int n = A.length;
    for (int i = n / 2 - 1; i >= 0; i--) {
        heapify(A, n, i);
    }
    return A;
}

private void heapify(int[] heap, int n, int i) {
    int smallest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;
    if (left < n && heap[left] < heap[smallest]) {
        smallest = left;
    }
    if (right < n && heap[right] < heap[smallest]) {
        smallest = right;
    }
    if (smallest != i) {
        swap(heap, i, smallest);
        heapify(heap, n, smallest); // keep sinking from the NEW index
    }
}

private void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

