public int[] heapQueriesExtractMin(int[][] A) {
    PriorityQueue<Integer> minHeap = new PriorityQueue<>();
    ArrayList<Integer> list = new ArrayList<>();
    for (int[] row : A) {
        int P = row[0];
        int Q = row[1];
        if (P == 1) {
            if (minHeap.size() > 0) {
                list.add(minHeap.poll());
            } else {
                list.add(-1);
            }
        } else {
            minHeap.add(Q);
        }
    }
    int[] res = new int[list.size()];
    for (int i = 0; i < res.length; i++) {
        res[i] = list.get(i);
    }
    return res;
}

public int minimumLargestElement(int[] A, int B) {
    int n = A.length;
    PriorityQueue<long[]> minHeap = new PriorityQueue<>((x, y) -> Long.compare(x[0], y[0]));
    long maxOriginal = 0;
    for (int val : A) {
        minHeap.add(new long[]{val, val}); // {current, original}
        if (val > maxOriginal) {
            maxOriginal = val;
        }
    }
    // every element must keep at least one copy of its original value
    long answer = maxOriginal;
    // N + B values are consumed in total: one per element, plus the B extra operations
    for (int taken = 0; taken < n + B; taken++) {
        long[] top = minHeap.poll();
        if (top[0] > answer) {
            answer = top[0];
        }
        minHeap.add(new long[]{top[0] + top[1], top[1]}); // always add the ORIGINAL
    }
    return (int) answer;
}

public int mishaAndCandies(int[] A, int B) {
    PriorityQueue<Long> minHeap = new PriorityQueue<>();
    for (int candies : A) {
        minHeap.add((long) candies);
    }
    long total = 0;
    while (minHeap.size() > 1) {
        long first = minHeap.poll();
        if (first > B) {
            break; // min is inedible, so every remaining box is too
        }
        total = total + first / 2;
        long leftover = first - first / 2; // ceil half, survives odd counts
        long second = minHeap.poll();
        minHeap.add(second + leftover); // the 'first' box is never reused
    }
    return (int) total;
}

public int maximumArraySumAfterBNegations(int[] A, int B) {
    PriorityQueue<Integer> minHeap = new PriorityQueue<>();
    for (int val : A) {
        minHeap.add(val);
    }
    int remaining = B;
    while (remaining > 0) {
        int min = minHeap.poll();
        if (min >= 0) {
            if (remaining % 2 == 1) {
                min = -min; // burn the odd leftover on the smallest value
            }
            minHeap.add(min);
            break; // all further flips would just toggle this same element
        }
        minHeap.add(-min);
        remaining = remaining - 1;
    }
    long sum = 0;
    for (int val : minHeap) {
        sum = sum + val;
    }
    return (int) sum;
}

public int[] expectedDeliveryTime(int[] A) {
    int n = A.length;
    PriorityQueue<Integer> leftMaxHeap = new PriorityQueue<>(Collections.reverseOrder());
    PriorityQueue<Integer> rightMinHeap = new PriorityQueue<>();
    int[] res = new int[n];
    leftMaxHeap.add(A[0]);
    res[0] = A[0];

    for (int i = 1; i < n; i++) {
        int maxOfLeftHalf = leftMaxHeap.peek();
        if (maxOfLeftHalf < A[i]) {
            rightMinHeap.add(A[i]);
        } else {
            leftMaxHeap.add(A[i]);
        }

        // invariant: |left| - |right| stays in {0, 1}, so left.peek() is the lower middle
        if (leftMaxHeap.size() - rightMinHeap.size() > 1) {
            rightMinHeap.add(leftMaxHeap.poll());
        } else if (rightMinHeap.size() > leftMaxHeap.size()) {
            leftMaxHeap.add(rightMinHeap.poll());
        }

        res[i] = leftMaxHeap.peek();
    }
    return res;
}

public int finishMaximumJobs(int[] A, int[] B) {
    int n = A.length;
    Job[] jobs = new Job[n];
    for (int i = 0; i < n; i++) {
        jobs[i] = new Job(A[i], B[i]);
    }
    Arrays.sort(jobs, (a, b) -> Integer.compare(a.endTime, b.endTime));

    int prevEnd = 0;
    int jobsCount = 0;
    for (Job j : jobs) {
        if (j.startTime >= prevEnd) {
            prevEnd = j.endTime;
            jobsCount++;
        }
    }
    return jobsCount;
}

private static class Job {
    int startTime;
    int endTime;

    Job(int startTime, int endTime) {
        this.startTime = startTime;
        this.endTime = endTime;
    }
}

public int seatsMinimumJumps(String A) {
    final int MOD = 10000003;
    int n = A.length();

    int k = 0;
    for (int i = 0; i < n; i++) {
        if (A.charAt(i) == 'x') {
            k++;
        }
    }
    if (k <= 1) {
        return 0;
    }

    int[] shifted = new int[k];
    int idx = 0;
    for (int i = 0; i < n; i++) {
        if (A.charAt(i) == 'x') {
            shifted[idx] = i - idx;   // collapse the gaps: contiguous targets become one meeting point
            idx++;
        }
    }

    int median = shifted[k / 2];
    long jumps = 0;
    for (int i = 0; i < k; i++) {
        jumps = (jumps + Math.abs(shifted[i] - median)) % MOD;
    }
    return (int) jumps;
}

public int assignMiceToHolesMinimumTime(int[] A, int[] B) {
    Arrays.sort(A);
    Arrays.sort(B);

    long max = 0;
    for (int i = 0; i < A.length; i++) {
        long diff = Math.abs((long) A[i] - (long) B[i]);
        if (diff > max) {
            max = diff;
        }
    }
    return (int) max;
}

public int waysToFormMaxHeap(int A) {
    final int MOD = 1000000007;

    long[][] nCr = new long[A + 1][A + 1];
    for (int i = 0; i <= A; i++) {
        nCr[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            nCr[i][j] = (nCr[i - 1][j - 1] + nCr[i - 1][j]) % MOD;
        }
    }

    long[] dp = new long[A + 1];
    dp[0] = 1;
    if (A >= 1) {
        dp[1] = 1;
    }
    for (int n = 2; n <= A; n++) {
        int left = leftSubtreeNodeCount(n);
        dp[n] = nCr[n - 1][left] * dp[left] % MOD * dp[n - 1 - left] % MOD;
    }
    return (int) dp[A];
}

private int leftSubtreeNodeCount(int n) {
    int h = 0;
    while ((1 << (h + 1)) - 1 <= n) {
        h++;
    }
    // 2^h - 1 nodes sit fully above the last level; the last level fills left first
    int lastLevelNodes = n - ((1 << h) - 1);
    int leftCapacity = 1 << (h - 1);
    return (leftCapacity - 1) + Math.min(lastLevelNodes, leftCapacity);
}

public int anotherCoinProblemMinimumCoins(int A) {
    long remaining = A;
    int coins = 0;
    while (remaining > 0) {
        coins += (int) (remaining % 5);   // base-5 digit = number of 5^k coins taken
        remaining /= 5;
    }
    return coins;
}

