public int distributeCandyMinimum(int[] A) {
    int n = A.length;
    int candies = 0;
    int[] candy = new int[n];
    Arrays.fill(candy, 1);

    for (int i = 1; i < n; i++) {
        if (A[i] > A[i - 1]) {
            candy[i] = candy[i - 1] + 1;
        }
    }

    for (int i = n - 2; i >= 0; i--) {
        if (A[i] > A[i + 1]) {
            candy[i] = Math.max(candy[i + 1] + 1, candy[i]); // max, not assign - keeps pass 1 intact
        }
    }

    for (int i = 0; i < n; i++) {
        candies += candy[i];
    }
    return candies;
}

public ListNode mergeKSortedLists(ArrayList<ListNode> a) {
    PriorityQueue<ListNode> minHeap = new PriorityQueue<>((c, b) -> c.val - b.val);

    for (ListNode list : a) {
        if (list != null) {
            minHeap.add(list);
        }
    }

    ListNode dummyHead = new ListNode(-1);
    ListNode tail = dummyHead;
    while (!minHeap.isEmpty()) {
        ListNode node = minHeap.poll();
        if (node.next != null) {
            minHeap.add(node.next); // push the successor BEFORE detaching
        }
        node.next = null; // detach, else the old tail gets spliced in
        tail.next = node;
        tail = tail.next;
    }
    return dummyHead.next;
}

public int[] aThLargestElement(int A, int[] B) {
    PriorityQueue<Integer> minHeap = new PriorityQueue<>(); // min-heap, though it tracks the LARGEST A
    int n = B.length;
    int[] res = new int[n];
    Arrays.fill(res, -1);

    for (int i = 0; i < n; i++) {
        minHeap.add(B[i]);
        if (i >= A - 1) {
            if (minHeap.size() > A) {
                minHeap.poll();
            }
            int min = minHeap.peek(); // smallest of the top A = Ath largest
            res[i] = min;
        }
    }
    return res;
}

public int flipkartInventoryManagement(int[] A, int[] B) {
    long MOD = 1_000_000_007L;
    PriorityQueue<Integer> minHeap = new PriorityQueue<>();
    int n = A.length;
    Item[] items = new Item[n];
    for (int i = 0; i < n; i++) {
        items[i] = new Item(A[i], B[i]);
    }
    Arrays.sort(items, Comparator.comparingInt(item -> item.expiry));

    for (Item item : items) {
        minHeap.add(item.profit);
        if (minHeap.size() > item.expiry) { // strict: size == expiry is still feasible
            minHeap.poll();
        }
    }

    long maxProfit = 0;
    while (!minHeap.isEmpty()) {
        maxProfit = (maxProfit + minHeap.poll()) % MOD;
    }

    return (int) maxProfit;
}

private static class Item {
    int expiry;
    int profit;

    Item(int expiry, int profit) {
        this.expiry = expiry;
        this.profit = profit;
    }
}

public int[] productOfThreeLargest(int[] A) {
    int n = A.length;
    int[] B = new int[n];
    PriorityQueue<Integer> minHeap = new PriorityQueue<>();

    for (int i = 0; i < n; i++) {
        minHeap.add(A[i]);
        if (minHeap.size() > 3) {
            minHeap.poll();
        }

        if (minHeap.size() < 3) {
            B[i] = -1;
        } else {
            int first = minHeap.poll();
            int second = minHeap.poll();
            int third = minHeap.poll();
            B[i] = first * second * third;
            minHeap.add(first); // push back, else the heap empties out
            minHeap.add(second);
            minHeap.add(third);
        }
    }
    return B;
}

public int kthSmallestElementInSortedMatrix(int[][] A, int B) {
    int n = A.length;
    int m = A[0].length;
    PriorityQueue<int[]> minHeap = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));

    for (int i = 0; i < n && i < B; i++) {
        minHeap.add(new int[]{A[i][0], i, 0});
    }

    int ans = -1;
    for (int count = 0; count < B; count++) {
        int[] curr = minHeap.poll();
        ans = curr[0];
        int row = curr[1];
        int col = curr[2];
        if (col + 1 < m) {
            minHeap.add(new int[]{A[row][col + 1], row, col + 1}); // right only - rows are already seeded
        }
    }
    return ans;
}

public int kthSmallestElementBinarySearchOnValue(int[][] A, int B) {
    int n = A.length;
    int m = A[0].length;
    int low = A[0][0];
    int high = A[n - 1][m - 1];

    while (low < high) {
        int mid = low + (high - low) / 2;
        if (countLessThanOrEqual(A, mid) >= B) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low; // smallest value whose count reaches B - always a real element
}

private int countLessThanOrEqual(int[][] A, int target) {
    int n = A.length;
    int m = A[0].length;
    int count = 0;
    int row = n - 1;
    int col = 0;
    while (row >= 0 && col < m) {
        if (A[row][col] <= target) {
            count += row + 1; // column is sorted, so everything above also fits
            col++;
        } else {
            row--;
        }
    }
    return count;
}

